# SPDX-License-Identifier: Apache-2.0
# SPDX-FileCopyrightText: Copyright contributors to the vLLM project
import torch
from torch._subclasses.fake_tensor import FakeTensor

from vllm.triton_utils import tl, triton


@triton.jit
def moe_fused_mul_sum_kernel(
    inputs_ptr,
    topk_weights_ptr,
    outputs_ptr,
    top_ids_ptr,
    expert_map_ptr,
    num_valid_tokens_ptr,
    stride_m,
    has_topk_ids: tl.constexpr,
    has_expert_map: tl.constexpr,
    has_num_valid: tl.constexpr,
    top_k: tl.constexpr,
    hidden_size: tl.constexpr,
    BLOCK_K: tl.constexpr,
):
    # One CTA owns one token's output row. Resolve which slots to sum once per
    # row (the decision is invariant over hidden tiles); the `if take` branch is
    # block-uniform, so padding slots are skipped rather than masked-and-loaded.
    pid_m = tl.program_id(0)
    # Bound to the real recv rows [0, num_recv). Under cudagraph decode the grid
    # is the static padded token count, and padding rows past num_recv carry
    # stale ids and stale NaN in `inputs`; returning before any load leaves their
    # output rows untouched instead of summing that garbage. The constexpr guard
    # short-circuits, so num_valid_tokens_ptr is only read when it is provided.
    if has_num_valid and pid_m >= tl.load(num_valid_tokens_ptr).to(tl.int32):
        return
    w_row = topk_weights_ptr + pid_m * top_k

    takes = ()
    weights = ()
    if has_topk_ids:
        any_valid = 0
        for n in tl.static_range(top_k):
            id_val = tl.load(top_ids_ptr + pid_m * top_k + n)
            valid = id_val >= 0
            any_valid += valid.to(tl.int32)
            take = valid
            if has_expert_map:
                local_id = tl.load(expert_map_ptr + tl.where(valid, id_val, 0))
                take = valid & (local_id >= 0)
            takes += (take,)  # type: ignore[assignment]
            weights += (tl.load(w_row + n).to(tl.float32),)  # type: ignore[assignment]
        # All-padding rows early-return untouched (decode contract past num_recv).
        if any_valid == 0:
            return
    else:
        for n in tl.static_range(top_k):
            takes += (True,)  # type: ignore[assignment]
            weights += (tl.load(w_row + n).to(tl.float32),)  # type: ignore[assignment]

    n_tiles: tl.constexpr = (hidden_size + BLOCK_K - 1) // BLOCK_K
    a_row = inputs_ptr + pid_m * stride_m
    out_row = outputs_ptr + pid_m * hidden_size

    for t in tl.range(0, n_tiles):
        offs_k = t * BLOCK_K + tl.arange(0, BLOCK_K)
        kmask = offs_k < hidden_size
        acc = tl.zeros((BLOCK_K,), dtype=tl.float32)
        for n in tl.static_range(top_k):
            if takes[n]:
                a = tl.load(a_row + n * hidden_size + offs_k, mask=kmask, other=0.0)
                acc += a.to(tl.float32) * weights[n]
        tl.store(out_row + offs_k, acc.to(outputs_ptr.dtype.element_ty), mask=kmask)


def _heuristic_config(
    hidden_size: int,
    element_size: int,
):
    is_fp32 = element_size > 2
    max_block_k = 256 if is_fp32 else 512
    BLOCK_K = max(128, min(triton.next_power_of_2(hidden_size), max_block_k))
    num_warps = 4 if is_fp32 else 2
    num_stages = 3
    return BLOCK_K, num_warps, num_stages


def moe_fused_mul_sum(
    inputs: torch.Tensor,
    topk_weights: torch.Tensor,
    outputs: torch.Tensor | None = None,
    topk_ids: torch.Tensor | None = None,
    expert_map: torch.Tensor | None = None,
    num_valid_tokens: torch.Tensor | None = None,
) -> torch.Tensor:
    """
    Fused kernel for MoE (Mixture of Experts) to perform weighted summation
    of expert outputs.

    Args:
        inputs: The output from experts.
            Shape: (num_tokens, top_k, hidden_size).
        topk_weights: The weights assigned to each expert for each token.
            Shape: (num_tokens, top_k).
        outputs: Optional pre-allocated output tensor.
            Shape: (num_tokens, hidden_size).
        topk_ids: Optional indices of the top-k experts. Shape:
            (num_tokens, top_k). A value of -1 marks a slot the expert GEMM
            skipped; those slots are excluded from the sum. When provided, rows
            with all top ids < 0 (worst-case padding) are skipped and their
            output rows left untouched. Required when `expert_map` is provided.
        expert_map: Optional mapping for Expert Parallelism. A value < 0
            indicates an invalid token/expert pair that will be skipped. Only
            needed when `topk_ids` may contain non-local expert ids; if every
            non-(-1) id is already a local expert, leave it None to skip the
            redundant per-slot lookup.
        num_valid_tokens: Optional device scalar (1-element tensor) holding the
            number of real token rows (num_recv for a decode dispatch). When
            provided, rows past it are left untouched, so the static cudagraph
            grid never sums stale padding rows. Pass the token count, not
            token*top_k.

    Returns:
        The fused weighted sum of expert outputs.
        Shape: (num_tokens, hidden_size).
    """
    assert inputs.ndim == 3
    assert topk_weights.ndim == 2
    assert inputs.is_contiguous()
    assert topk_weights.is_contiguous()
    assert inputs.dtype in (torch.float32, torch.float16, torch.bfloat16)
    assert topk_weights.dtype in (torch.float32, torch.float16, torch.bfloat16)

    num_tokens, top_k, hidden_size = inputs.shape
    output_shape = (num_tokens, hidden_size)
    if outputs is None:
        outputs = torch.empty(output_shape, dtype=inputs.dtype, device=inputs.device)

    assert outputs.shape == output_shape
    assert topk_weights.shape == (num_tokens, top_k)
    assert expert_map is None or topk_ids is not None, (
        "topk_ids is required to interpret expert_map"
    )
    if topk_ids is not None:
        assert topk_ids.shape == (num_tokens, top_k)
        assert topk_ids.is_contiguous()
        assert topk_ids.dtype in (torch.int32, torch.int64)

    if not isinstance(inputs, FakeTensor):
        BLOCK_K, num_warps, num_stages = _heuristic_config(
            hidden_size,
            inputs.element_size(),
        )
        grid = (num_tokens,)
        moe_fused_mul_sum_kernel[grid](
            inputs,
            topk_weights,
            outputs,
            topk_ids,
            expert_map,
            num_valid_tokens,
            top_k * hidden_size,
            topk_ids is not None,
            expert_map is not None,
            num_valid_tokens is not None,
            top_k,
            hidden_size,
            BLOCK_K,
            num_warps=num_warps,
            num_stages=num_stages,
        )

    return outputs

// ===== FILE: vllm-env/lib/python3.12/site-packages/vllm/v1/attention/backends/mla/cpu_mla.py =====
# SPDX-License-Identifier: Apache-2.0
# SPDX-FileCopyrightText: Copyright contributors to the vLLM project
"""CPU MLA backend.

This is a *reference-quality* MLA backend for the CPU platform. It is
intended to make DeepSeek-V2/V3 style models runnable on CPU (for
functional verification, tiny-model smoke tests and CI), not to be
performant. The prefill path is a plain PyTorch SDPA and the decode
path forwards to the existing CPU decode kernel
`torch.ops._C.mla_decode_kvcache` (see csrc/cpu/mla_decode.cpp).

Key design points:

* We inherit the shared MLA scaffolding (`MLACommonBackend`,
  `MLACommonImpl`, `MLACommonMetadata`) so that the same
  ``forward_impl`` in ``MLAAttention`` orchestrates weight-absorbed
  decode (MQA) and non-absorbed prefill (MHA) for us.
* The parent ``MLACommonImpl.__init__`` tries to pick a GPU prefill
  kernel (flash_attn / flashinfer / cudnn / trtllm) and raises when
  none of them are available. On CPU none of them apply, so we
  bypass that logic and set the attributes ourselves.
* Chunked prefill and prefix caching are disabled by the CPU platform
  when ``use_mla`` is set.
* The CPU decode kernel only supports ``head_dim=576``,
  ``v_head_dim=512`` and ``block_size=16`` today; the platform layer
  forces ``block_size=16`` for MLA models.
"""

from typing import ClassVar

import torch

from vllm import _custom_ops as ops
from vllm.config.cache import CacheDType
from vllm.logger import init_logger
from vllm.model_executor.layers.attention.mla_attention import (
    MLACommonBackend,
    MLACommonImpl,
    MLACommonMetadata,
)
from vllm.v1.attention.backend import (
    AttentionLayer,
    AttentionType,
    MultipleOf,
)

logger = init_logger(__name__)


class CPUMLABackend(MLACommonBackend):
    """Attention backend descriptor for CPU MLA."""

    supported_dtypes: ClassVar[list[torch.dtype]] = [
        torch.float16,
        torch.bfloat16,
        torch.float32,
    ]
    supported_kv_cache_dtypes: ClassVar[list[CacheDType]] = ["auto"]

    @classmethod
    def get_supported_head_sizes(cls) -> list[int]:
        # DeepSeek-V2/V3 latent cache size = kv_lora_rank(512)+rope(64)=576.
        # The current CPU decode kernel only compiles for this size.
        return [576]

    @staticmethod
    def get_supported_kernel_block_sizes() -> list[int | MultipleOf]:
        return [16]

    @classmethod
    def supports_block_size(cls, block_size: int | None) -> bool:
        return block_size is None or block_size == 16

    @staticmethod
    def get_name() -> str:
        return "CPU_MLA"

    @staticmethod
    def get_impl_cls() -> type["CPUMLAImpl"]:
        return CPUMLAImpl


class CPUMLAImpl(MLACommonImpl[MLACommonMetadata]):
    """CPU implementation of MLA attention.

    See module docstring for the overall design. This class only
    overrides the parts of the parent that would otherwise pull in
    CUDA-only dependencies.
    """

    # Decode always returns the softmax lse if the parent needs it, but
    # CPU decode currently only produces the output tensor. Report False
    # so DCP / cross-batch reductions are not requested from us.
    can_return_lse_for_decode: bool = False

    def __init__(
        self,
        num_heads: int,
        head_size: int,
        scale: float,
        num_kv_heads: int,
        alibi_slopes: list[float] | None,
        sliding_window: int | None,
        kv_cache_dtype: str,
        logits_soft_cap: float | None,
        attn_type: str,
        kv_sharing_target_layer_name: str | None,
        # MLA-specific arguments (forwarded from `MLAAttention`).
        **mla_args,
    ) -> None:
        # NOTE: We deliberately skip ``MLACommonImpl.__init__`` because it
        # tries to pick a GPU prefill kernel and raises on CPU. Instead we
        # replicate the attribute setup here and then wire our own hooks.
        if kv_sharing_target_layer_name is not None:
            raise NotImplementedError("KV sharing is not supported for MLA")
        if attn_type != AttentionType.DECODER:
            raise NotImplementedError("CPU MLA only supports decoder self-attention.")
        unsupported = [alibi_slopes, sliding_window, logits_soft_cap]
        if any(unsupported):
            raise NotImplementedError(
                "CPU MLA does not support alibi_slopes / sliding_window / "
                "logits_soft_cap."
            )

        self.num_heads = num_heads
        self.head_size = head_size
        self.scale = float(scale)
        self.num_kv_heads = num_kv_heads
        self.kv_cache_dtype = kv_cache_dtype

        self.q_lora_rank = mla_args["q_lora_rank"]
        self.kv_lora_rank = mla_args["kv_lora_rank"]
        self.qk_nope_head_dim = mla_args["qk_nope_head_dim"]
        self.qk_rope_head_dim = mla_args["qk_rope_head_dim"]
        self.qk_head_dim = mla_args["qk_head_dim"]
        self.v_head_dim = mla_args["v_head_dim"]
        self.kv_b_proj = mla_args["kv_b_proj"]
        self.indexer = mla_args.get("indexer")
        self.q_pad_num_heads = mla_args.get("q_pad_num_heads")
        self.supports_quant_query_input = False

        # Never take the flashinfer specialisation of ``_concat_k_nope_k_pe``.
        self._use_flashinfer_concat_mla_k = False

        # We do not need V padding since our SDPA prefill takes k / v with
        # matching head dims.
        self._pad_v = False

        # Distributed / context-parallel bookkeeping expected by the parent.
        self.dcp_world_size = 1
        self.cp_kv_cache_interleave_size = 1

    # ------------------------------------------------------------------
    # Decode (MQA)
    # ------------------------------------------------------------------
    def forward_mqa(
        self,
        q: torch.Tensor | tuple[torch.Tensor, torch.Tensor],
        kv_c_and_k_pe_cache: torch.Tensor,
        attn_metadata: MLACommonMetadata,
        layer: AttentionLayer,
    ) -> tuple[torch.Tensor, torch.Tensor | None]:
        assert attn_metadata.decode is not None
        # The parent hands us either a tuple (q_nope, q_pe) or a single
        # tensor already concatenated. CPU decode kernel wants a single
        # (bs, num_heads, head_dim=kv_lora_rank+rope) contiguous tensor.
        if isinstance(q, tuple):
            q = torch.cat(q, dim=-1)
        q = q.contiguous()

        bs, num_heads, _ = q.shape
        out = torch.zeros(
            bs, num_heads, self.kv_lora_rank, dtype=q.dtype, device=q.device
        )

        # The CPU kernel is templated on int32 block_tables / seq_lens.
        block_table = attn_metadata.decode.block_table.to(torch.int32)
        seq_lens = attn_metadata.decode.seq_lens.to(torch.int32)

        ops.mla_decode_kvcache_cpu(
            out,
            q,
            kv_c_and_k_pe_cache,
            self.scale,
            block_table,
            seq_lens,
        )
        # The parent only consumes the LSE when DCP is active, which we
        # disable, so returning None here is safe.
        return out, None

