/// Parameters structure
template <
  typename ThreadblockSwizzle,
  typename ParamsA,
  typename TensorRefA,
  typename ParamsB,
  typename TensorRefB,
  typename ParamsE,
  typename TensorRefE>
struct SparseParamsBase
{
  //
  // Data members
  //

  cutlass::gemm::GemmCoord problem_size{};
  cutlass::gemm::GemmCoord grid_tiled_shape{};
  int swizzle_log_tile;
  ParamsA params_A{};
  TensorRefA ref_A{};
  ParamsB params_B{};
  TensorRefB ref_B{};
  ParamsE params_E{};
  TensorRefE ref_E{};
  int gemm_k_iterations{0};
  int gemm_k_size{0};

  //
  // Host dispatch API
  //

  /// Default constructor
  SparseParamsBase() = default;

  /// Constructor
  CUTLASS_HOST_DEVICE
  SparseParamsBase(
    cutlass::gemm::GemmCoord const & problem_size,
    cutlass::gemm::GemmCoord const & grid_tiled_shape,
    TensorRefA ref_A,
    TensorRefB ref_B,
    TensorRefE ref_E,
    int const mma_shape_k)
  :
    problem_size(problem_size),
    grid_tiled_shape(grid_tiled_shape),
    swizzle_log_tile(ThreadblockSwizzle().get_log_tile(grid_tiled_shape)),
    params_A(ref_A.layout()),
    ref_A(ref_A),
    params_B(ref_B.layout()),
    ref_B(ref_B),
    params_E(ref_E.layout()),
    ref_E(ref_E)
  {
    int total_gemm_k_iterations = (problem_size.k() + mma_shape_k - 1) / mma_shape_k;
    int gemm_k_iterations = (total_gemm_k_iterations + grid_tiled_shape.k() - 1) / grid_tiled_shape.k();

    gemm_k_size = gemm_k_iterations * mma_shape_k;
  }
};

